function getStepEntries(rev = {}) {
  const entries = [];
  for (const step of STEPS) {
    if (rev?.[step.key]) entries.push([step.key, rev[step.key]]);
  }
  if (rev?.manutencao) entries.push(["manutencao", rev.manutencao]);
  return entries;
}

function inferWeakSubjectFromSimulados(simulados = []) {
  const latest = simulados[simulados.length - 1];
  if (!latest) return null;
  const rows = Array.isArray(latest.porArea) ? latest.porArea : [];
  if (rows.length > 0) {
    const normalized = rows
      .map((row) => {
        const total = Number(row.total || row.questoes || 0);
        const acertos = Number(row.acertos || row.hits || 0);
        if (total <= 0) return null;
        return {
          area: row.area || row.esp || row.nome || null,
          pct: (acertos / total) * 100,
        };
      })
      .filter(Boolean);
    if (normalized.length > 0) {
      normalized.sort((a, b) => a.pct - b.pct);
      return normalized[0].area || null;
    }
  }
  return null;
}

function collectClinicalCaseSignals(casosProgresso = {}, today = todayStr()) {
  const due = Object.entries(casosProgresso)
    .filter(([, item]) => item?.proximaData && item.proximaData <= today)
    .map(([casoId, item]) => {
      const match = CASOS_CLINICOS.find(c => c.id === casoId);
      return {
        casoId,
        proximaData: item.proximaData,
        atualizadoEm: item.atualizadoEm || null,
        temaName: match ? (match.tema || match.subarea) : null,
      };
    });
  return {
    dueCount: due.length,
    dueItems: due.slice(0, 20),
  };
}

function countConsolidatedCorpusAreas(temas = []) {
  const areas = new Set();
  for (const tema of temas) {
    if (!tema || tema.unstarted) continue;
    const rev = tema.rev || {};
    const isConsolidated = Boolean(rev.d21?.done || rev.manutencao);
    const area = tema.esp || tema.area || tema.materia || null;
    if (isConsolidated && area) areas.add(String(area).trim());
  }
  return areas.size;
}

function workloadLevelByMinutes(minutes = 0) {
  if (minutes > 120) return "high";
  if (minutes > 60) return "moderate";
  return "ok";
}

function maxWorkloadLevel(a = "ok", b = "ok") {
  const rank = { ok: 0, moderate: 1, high: 2 };
  return (rank[b] || 0) > (rank[a] || 0) ? b : a;
}

/**
 * Analisa erros recentes (revisoes + simulados) e retorna o tipo dominante
 * com sua acao corretiva quando houver amostra suficiente.
 */
function collectDominantErrorSignal(temas = [], simulados = [], plat = "res") {
  const fromReviews = temas.flatMap((tema) =>
    STEPS.flatMap((step) => {
      const review = tema.rev?.[step.key];
      if (!review?.done) return [];
      const structured = Array.isArray(review.erros) ? review.erros : [];
      const fallback = Array.isArray(review.motivosErro)
        ? review.motivosErro.map((tipoErro) => ({ tipoErro, acertou: false }))
        : [];
      return [...structured, ...fallback];
    })
  );
  const fromSimulados = simulados.flatMap((sim) =>
    (sim.questoesErradas || []).map((q) => ({
      tipoErro: q.tipoErro,
      acertou: false,
      tempoExcedido: Boolean(q.tempoExcedido),
    }))
  );
  const allErrors = [...fromReviews, ...fromSimulados];
  const dominant = dominantErrorType(allErrors);
  const total = allErrors.length;
  const summary = summarizeErrors(allErrors);
  const dominantCount = dominant ? (summary[dominant] || 0) : 0;
  const isStrong = total >= 5 && dominantCount >= 3;
  const correctiveAction = isStrong ? getCorrectiveAction(dominant) : null;

  return {
    dominantError: isStrong ? dominant : null,
    dominantErrorCount: dominantCount,
    dominantErrorTotal: total,
    dominantErrorAction: correctiveAction,
    dominantErrorIsStrong: isStrong,
  };
}

export function collectMentorSchedulerSignals(temas = [], options = {}) {
  const today = options.today || todayStr();
  const projectionDays = options.projectionDays || 14;
  const workloadProjection = getWorkloadProjection(temas, projectionDays);
  const workloadEntries = Object.values(workloadProjection);
  const todayEntry = workloadProjection[today] || {
    count: 0,
    estimatedMinutes: 0,
    overloadLevel: "ok",
  };
  const next7DaysMinutes = workloadEntries
    .slice(0, 7)
    .reduce((sum, day) => sum + (day?.estimatedMinutes || 0), 0);
  const maxDayMinutes = workloadEntries.reduce((max, day) => Math.max(max, day?.estimatedMinutes || 0), 0);
  const overloadDays = workloadEntries.filter((day) => day?.overloadLevel !== "ok").length;

  let overdueCount = 0;
  let dueTodayCount = 0;
  let maxDelayDays = 0;
  let missingReviewedAtCount = 0;
  let missingRatingWarnings = 0;
  let reviewHistoryEvents = 0;
  let computedDueMinutes = 0;
  const dueItems = [];
  const relearningItems = [];

  for (const tema of temas) {
    if (!tema || tema.unstarted) continue;
    const rev = tema.rev || {};
    const history = Array.isArray(rev.reviewHistory) ? rev.reviewHistory : [];
    reviewHistoryEvents += history.length;
    if (rev.meta?.schedulerWarning === "missing_rating") {
      missingRatingWarnings += 1;
    }
    if (rev.phase === "relearning" || rev.relearning?.startedAt) {
      relearningItems.push({
        temaId: tema.id,
        temaNome: tema.nome,
        esp: tema.esp,
        fromStep: rev.relearning?.fromStep || null,
        targetStep: rev.relearning?.targetStep || null,
        startedAt: rev.relearning?.startedAt || null,
      });
    }

    for (const [stepKey, step] of getStepEntries(rev)) {
      if (!step) continue;
      if (step.skipped || step.skipReason === "dominio_previo" || step.skippeadoPorDominio) {
        continue;
      }
      if (step.done && !step.reviewedAt) {
        missingReviewedAtCount += 1;
      }
      if (step.done && step.acerto == null) {
        missingRatingWarnings += 1;
      }
      if (step.done || !step.date) continue;

      if (step.date < today) {
        computedDueMinutes += getEstimatedMinutesForStep(stepKey, step);
        overdueCount += 1;
        const delayDays = Math.max(0, diffDays(step.date, today));
        maxDelayDays = Math.max(maxDelayDays, delayDays);
        dueItems.push({
          temaId: tema.id,
          temaNome: tema.nome,
          esp: tema.esp,
          stepKey,
          label: getReviewDisplayLabel(tema, stepKey),
          date: step.date,
          delayDays,
          phase: step.phase || null,
        });
      } else if (step.date === today) {
        computedDueMinutes += getEstimatedMinutesForStep(stepKey, step);
        dueTodayCount += 1;
        dueItems.push({
          temaId: tema.id,
          temaNome: tema.nome,
          esp: tema.esp,
          stepKey,
          label: getReviewDisplayLabel(tema, stepKey),
          date: step.date,
          delayDays: 0,
          phase: step.phase || null,
        });
      }
    }
  }

  dueItems.sort((a, b) => (a.date || "").localeCompare(b.date || ""));
  const nextDueItem = dueItems[0] || null;
  const trueRetention = calcTrueRetentionDetailed(temas);
  const effectiveTodayMinutes = Math.max(todayEntry.estimatedMinutes || 0, computedDueMinutes);
  const effectiveOverloadLevelToday = maxWorkloadLevel(
    todayEntry.overloadLevel || "ok",
    workloadLevelByMinutes(effectiveTodayMinutes)
  );

  return {
    workloadProjection,
    todayCount: todayEntry.count || 0,
    todayMinutes: effectiveTodayMinutes,
    next7DaysMinutes,
    overloadLevelToday: effectiveOverloadLevelToday,
    overloadDays,
    maxDayMinutes,
    overdueCount,
    dueTodayCount,
    maxDelayDays,
    nextDueItem,
    relearningCount: relearningItems.length,
    relearningItems,
    missingRatingWarnings,
    missingReviewedAtCount,
    reviewHistoryEvents,
    trueRetentionPct: trueRetention.pct,
    trueRetentionN: trueRetention.n,
    trueRetentionTotalQuestoes: trueRetention.totalQuestoes,
    trueRetentionCollecting: trueRetention.collecting,
  };
}

export function buildMentorContext(state = {}, platArg, extras = {}) {
  const plat = platArg || state.plat || "res";
  const today = extras.today || todayStr();
  const platState = state[plat] || {};
  const temas = extras.temas || platState.temas || [];
  const simulados = extras.simulados || platState.simulados || [];
  const meta = extras.meta || state.meta || {};
  const temaStats = extras.temaStats || getTemaStatsFromLearningEvents(state.learningEvents || [], {
    plat,
    fallbackTemaStats: platState.temaStats || state.temaStats || {},
  });
  const scheduler = collectMentorSchedulerSignals(temas, {
    today,
    projectionDays: extras.projectionDays || 14,
  });

  const enamedAnalises = extras.enamedAnalises || state.enamedAnalises || [];
  const latestEnamed = enamedAnalises[enamedAnalises.length - 1] || null;
  const weakSubject = extras.weakSubject
    || meta?.areaPuxouBaixo
    || inferWeakSubjectFromSimulados(simulados);
  const clinical = collectClinicalCaseSignals(platState.casosProgresso || {}, today);
  const userAvailableMinutes = Number(meta?.tempoDisponivel || 0) > 0
    ? Number(meta.tempoDisponivel) * 60
    : null;
  // Espelha o alvo usado por rebalanceTodayWorkload (store.js) para a decisao
  // saber se HOJE esta de fato acima da capacidade e ainda ha o que aliviar.
  const rebalanceTargetMinutes = Number(userAvailableMinutes) > 0
    ? Math.max(60, Math.min(120, Number(userAvailableMinutes)))
    : 120;
  const rebalanceMaxItems = Number(meta?.maxRevisoesDia) > 0
    ? Number(meta.maxRevisoesDia)
    : 30;
  const operationalMode = deriveOperationalMode({
    scheduler,
    meta,
    today,
    plat,
    focusMode: state.focusMode,
    modoSimples: state.modoSimples,
    mentorMode: state.mentorMode,
    modoProva: state.modoProva,
    userAvailableMinutes,
  });
  const mastery = estimateStudentMastery({
    temas,
    temaStats,
    context: { plat, operationalMode },
  });
  const pendingExamAnalysis = Boolean(simulados.length > 0 && !latestEnamed);
  const errorSignal = collectDominantErrorSignal(temas, simulados, plat);
  const consolidatedCorpus = countConsolidatedCorpusAreas(temas);

  // ── Onboarding v2 signals ──────────────────────────────────────────────────
  const planSetup = meta?.planSetup || null;
  const scheduledTopics = (state.calendarProvider?.scheduledTopics) || [];
  const agendaItems = planSetup?.completedAt
    ? buildAgendaItems(temas, scheduledTopics, simulados, planSetup, plat, 30, today)
    : [];
  const agendaTodaySummary = getAgendaDaySummary(agendaItems, today);
  const firstAction = (planSetup?.completedAt && temas.length === 0)
    ? getFirstActionAfterOnboarding(scheduledTopics, planSetup, today)
    : null;
  const planHealth = planSetup?.feasibility?.status || null;

  const intention = meta.studyPlanIntention || null;
  let studyPlanIntentionNeedsReplan = false;
  if (intention) {
    const learningEvents = state.learningEvents || [];
    const adherence = calculate7DayAdherence(learningEvents, today);
    const reminderInfo = nextReminderFor(intention, today, adherence);
    studyPlanIntentionNeedsReplan = reminderInfo ? reminderInfo.needsReplan : false;
  }

  return {
    plat,
    today,
    meta,
    calendarProvider: state.calendarProvider || {},
    actionInbox: state.actionInbox || [],
    sessionReflections: state.sessionReflections || [],
    scheduler,
    consolidatedCorpus,
    operationalMode,
    mastery,
    enamed: latestEnamed,
    weakSubject: weakSubject || null,
    pendingExamAnalysis,
    clinical,
    readinessData: extras.readinessData || null,
    userAvailableMinutes,
    ankiDoneToday: (meta?.ankiAdesao?.datas || []).includes(today),
    lastWorkloadRebalance: meta?.lastWorkloadRebalance || null,
    rebalanceTargetMinutes,
    rebalanceMaxItems,
    lowEnergy: Boolean(extras.lowEnergy),
    exhaustionDetected: Boolean(extras.exhaustionDetected),
    dominantError: errorSignal.dominantError,
    dominantErrorAction: errorSignal.dominantErrorAction,
    dominantErrorIsStrong: errorSignal.dominantErrorIsStrong,
    firstAction,
    agendaTodaySummary,
    planHealth,
    studyPlanIntention: intention,
    studyPlanIntentionNeedsReplan,
  };
}
